/*
 Problem: 1096. Brace Expansion II
 Language: cpp
 Runtime: 11 ms (63.20%)
 Memory: 15.2 MB (53.57%)
 Tags: Hash Table, String, Backtracking, Stack, Breadth-First Search, Sorting
*/
class Solution {
public:
    vector<string> braceExpansionII(string s) {
        int i = 0;
        set<string> res = parseUnion(s, i);
        return vector<string>(res.begin(), res.end());
    }

private:
    set<string> parseUnion(string& s, int& i) {
        set<string> res = parseConcat(s, i);

        while (i < s.size() && s[i] == ',') {
            ++i;
            auto cur = parseConcat(s, i);
            res.insert(cur.begin(), cur.end());
        }

        return res;
    }

    set<string> parseConcat(string& s, int& i) {
        set<string> res = {""};

        while (i < s.size() && s[i] != '}' && s[i] != ',') {
            set<string> cur;

            if (s[i] == '{') {
                ++i;
                cur = parseUnion(s, i);
                ++i;
            } else {
                cur.insert(string(1, s[i++]));
            }

            set<string> next;

            for (auto& a : res)
                for (auto& b : cur)
                    next.insert(a + b);

            res = move(next);
        }

        return res;
    }
};
